# Let's construct some candidate graphs and test chromatic number
# We can use simple backtracking for coloring since n=14

def graph_from_edges(n, edges):
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return adj

def chromatic_number(adj, n):
    # backtracking with branch and bound
    best = n
    colors = [-1] * n

    def dfs(v, used_colors):
        nonlocal best
        if used_colors >= best:
            return
        if v == n:
            best = used_colors
            return
        # try existing colors
        forbidden = set()
        for u in adj[v]:
            if colors[u] != -1:
                forbidden.add(colors[u])
        for c in range(used_colors):
            if c not in forbidden:
                colors[v] = c
                dfs(v+1, used_colors)
                colors[v] = -1
                if best <= used_colors:
                    return
        # try new color
        if used_colors < best:
            colors[v] = used_colors
            dfs(v+1, used_colors+1)
            colors[v] = -1

    dfs(0, 0)
    return best

