def chromatic_number_exact(adj, n):
    # Use recursion with ordering and bounds
    best = n
    colors = [-1] * n

    # Order vertices by degree descending for efficiency
    order = list(range(n))
    order.sort(key=lambda v: -len(adj[v]))

    # Map position to original vertex
    pos_to_v = order

    def dfs(pos, used_colors):
        nonlocal best
        if used_colors >= best:
            return
        if pos == n:
            best = used_colors
            return
        v = pos_to_v[pos]
        forbidden = set()
        for u in adj[v]:
            if colors[u] != -1:
                forbidden.add(colors[u])
        for c in range(used_colors):
            if c not in forbidden:
                colors[v] = c
                dfs(pos+1, used_colors)
                colors[v] = -1
                if best <= used_colors:
                    return
        if used_colors < best:
            colors[v] = used_colors
            dfs(pos+1, used_colors+1)
            colors[v] = -1

    dfs(0, 0)
    return best

