# Check for odd cycle
def is_bipartite(adj, n):
    color = [-1] * n
    from collections import deque
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            q = deque([start])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

print("Bipartite?", is_bipartite(adj, n))
print("Chi >= 3?", not is_bipartite(adj, n))

