# Thorough check of chromatic number for this circulant graph

def chromatic_number_exact_full(adj, n):
    # Check all possible colorings up to k colors
    # Use DFS with pruning
    for k in range(1, n+1):
        colors = [-1] * n
        found = [False]

        # Order vertices by degree for efficiency
        order = list(range(n))
        order.sort(key=lambda v: -len(adj[v]))
        pos_to_v = order

        def dfs(pos):
            if found[0]:
                return
            if pos == n:
                found[0] = True
                return
            v = pos_to_v[pos]
            forbidden = set()
            for u in adj[v]:
                if colors[u] != -1:
                    forbidden.add(colors[u])
            for c in range(k):
                if c not in forbidden:
                    colors[v] = c
                    dfs(pos+1)
                    colors[v] = -1
                    if found[0]:
                        return

        dfs(0)
        if found[0]:
            return k
    return n

